SELECT 

WHERE (CAST(#{beforeId} AS BIGINT) IS NULL OR p.id < CAST(#{beforeId} AS BIGINT))

ORDER BY p.id DESC LIMIT #{limit}

SELECT 

WHERE p.user_id = #{userId}
  AND (CAST(#{beforeId} AS BIGINT) IS NULL OR p.id < CAST(#{beforeId} AS BIGINT))

ORDER BY p.id DESC LIMIT #{limit}

SELECT 

WHERE p.id > #{afterId}

ORDER BY p.id DESC

